#!/bin/sh
rootfs_builder_menu(){ while :; do c=$(ui_menu 'RootFS builder and manager' 'Portable wrappers for common rootfs workflows.' discover 'Discover root filesystems' debootstrap 'Build Debian/Devuan rootfs' alpine 'Build Alpine rootfs' arch 'Build Arch rootfs' validate 'Validate selected rootfs' mount 'Generate mount/chroot helper' archive 'Archive selected rootfs' clone 'Clone rootfs' packages 'Inventory rootfs packages' config 'Copy host configuration into rootfs' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in discover) run_capture RootFS sh -c 'find /root /AOK /opt/AOK -maxdepth 4 -type f -name os-release -print 2>/dev/null';; debootstrap) ensure_tool debootstrap debootstrap || continue; suite=$(ui_input RootFS 'Suite (e.g. trixie, excalibur)' trixie) || continue; arch=$(ui_input RootFS 'Architecture' arm64) || continue; dest=$(ui_input RootFS 'Destination' "/root/$suite-$arch") || continue; mirror=$(ui_input RootFS 'Mirror URL' http://deb.debian.org/debian) || continue; run_capture debootstrap as_root debootstrap --arch="$arch" --variant=minbase "$suite" "$dest" "$mirror";; alpine) v=$(ui_input Alpine 'Version branch' v3.22) || continue; arch=$(ui_input Alpine 'Architecture' aarch64) || continue; dest=$(ui_input Alpine 'Destination' "/root/alpine-$arch") || continue; mkdir -p "$dest"; ui_msg Alpine "Use apk --root '$dest' --arch '$arch' --initdb add alpine-base after configuring repositories for $v.";; arch) ui_msg Arch 'Use pacstrap/pacman --root when available. Architecture support depends on the host repositories.';; validate) r=$(ui_input Validate 'Rootfs path' /root/rootfs) || continue; run_capture Validate sh -c "test -f '$r/etc/os-release'; test -x '$r/bin/sh'; ls -ld '$r'/dev '$r'/proc '$r'/sys '$r'/run 2>/dev/null; file '$r/bin/sh'";; mount) r=$(ui_input Helper 'Rootfs path' /root/rootfs) || continue; out="$CURRENT_HOME/bin/chroot-$(basename "$r")"; mkdir -p "$CURRENT_HOME/bin"; write_file "$out" 755 "#!/bin/sh\nROOT='$r'\nmount --rbind /dev \"\$ROOT/dev\"\nmount -t proc proc \"\$ROOT/proc\"\nmount --rbind /sys \"\$ROOT/sys\"\nmkdir -p \"\$ROOT/run\"\nmount --bind /run \"\$ROOT/run\"\nchroot \"\$ROOT\" /bin/sh"; ui_msg Helper "Created $out";; archive) r=$(ui_input Archive 'Rootfs path' /root/rootfs) || continue; o=$(ui_input Archive 'Output' rootfs.tar.zst) || continue; run_capture Archive sh -c "tar -C '$r' -cf - . | zstd -T0 -o '$o'";; clone) r=$(ui_input Clone 'Source rootfs' /root/rootfs) || continue; d=$(ui_input Clone 'Destination' /root/rootfs-copy) || continue; run_capture Clone cp -a "$r" "$d";; packages) r=$(ui_input Inventory 'Rootfs path' /root/rootfs) || continue; if [ -f "$r/var/lib/dpkg/status" ]; then awk '/^Package:|^Version:/{printf "%s ", $2} /^Version:/{print ""}' "$r/var/lib/dpkg/status" >"$TMP_DIR/rpkgs"; elif [ -f "$r/lib/apk/db/installed" ]; then awk '/^P:|^V:/{printf "%s ",substr($0,3)} /^V:/{print ""}' "$r/lib/apk/db/installed" >"$TMP_DIR/rpkgs"; fi; ui_text Packages "$(cat "$TMP_DIR/rpkgs" 2>/dev/null)";; config) r=$(ui_input Copy 'Rootfs path' /root/rootfs) || continue; cp -L /etc/resolv.conf "$r/etc/resolv.conf" 2>/dev/null; cp /etc/hosts "$r/etc/hosts" 2>/dev/null; ui_msg Copy 'Copied resolv.conf and hosts.';; back) return;; esac; done; }
